package com.cyancoder.aiorchestrator.service;
import com.cyancoder.aiorchestrator.api.dto.*;import com.cyancoder.aiorchestrator.api.dto.AiArtifactContracts.*;import com.cyancoder.aiorchestrator.client.impl.InternalServiceHttpSupport;import com.cyancoder.aiorchestrator.domain.AiArtifactJob;import com.cyancoder.aiorchestrator.repo.AiArtifactJobRepository;import com.fasterxml.jackson.databind.ObjectMapper;import java.time.Instant;import java.util.*;import java.util.concurrent.Executor;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.web.server.ResponseStatusException;
@Service public class AiArtifactJobService{private final AiArtifactJobRepository jobs;private final AiProviderProfileService profiles;private final AiOperationService operations;private final InternalServiceHttpSupport http;private final ObjectMapper json;private final Executor executor;public AiArtifactJobService(AiArtifactJobRepository jobs,AiProviderProfileService profiles,AiOperationService operations,InternalServiceHttpSupport http,ObjectMapper json,@Qualifier("aiArtifactExecutor")Executor executor){this.jobs=jobs;this.profiles=profiles;this.operations=operations;this.http=http;this.json=json;this.executor=executor;}
 public ArtifactJobView start(String tenant,String site,String actor,CreateArtifactJobRequest r){if(!Set.of(AiOperationRequest.AiOperationType.GENERATE_IMAGE,AiOperationRequest.AiOperationType.GENERATE_AUDIO,AiOperationRequest.AiOperationType.GENERATE_VIDEO).contains(r.operation()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Artifact jobs support image, audio, or video generation");var profile=profiles.require(tenant,site,r.providerProfileKey());String modality=r.operation().name().substring("GENERATE_".length());if(!profile.getModalities().contains(modality))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Provider profile does not support "+modality);if(!r.mimeType().toLowerCase(Locale.ROOT).startsWith(modality.toLowerCase(Locale.ROOT)+"/"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"mimeType does not match generated modality");AiArtifactJob j=new AiArtifactJob();j.setJobId(UUID.randomUUID().toString());j.setTenantKey(tenant);j.setSiteKey(blank(site));j.setActor(actor);j.setStatus("QUEUED");j.setOperation(r.operation());j.setInstructions(r.instructions());j.setInput(r.input());j.setProviderProfileKey(r.providerProfileKey());j.setAssets(r.assets()==null?List.of():r.assets());j.setRequestedMimeType(r.mimeType());j.setFileName(r.fileName());j.setRetentionDays(r.retentionDays()==null?30:r.retentionDays());j.setCreatedAt(Instant.now());jobs.save(j);executor.execute(()->run(j.getJobId()));return view(j);}
 public List<ArtifactJobView> list(String tenant,String site){return jobs.findTop50ByTenantKeyAndSiteKeyOrderByCreatedAtDesc(tenant,blank(site)).stream().map(this::view).toList();}public ArtifactJobView get(String tenant,String site,String id){return view(scoped(tenant,site,id));}public ArtifactJobView cancel(String tenant,String site,String id){AiArtifactJob j=scoped(tenant,site,id);if(Set.of("SUCCEEDED","FAILED","CANCELLED").contains(j.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Artifact job is already terminal");j.setStatus("CANCEL_REQUESTED");return view(jobs.save(j));}
 private void run(String id){AiArtifactJob j=jobs.findById(id).orElse(null);if(j==null)return;if("CANCEL_REQUESTED".equals(j.getStatus())){j.setStatus("CANCELLED");j.setCompletedAt(Instant.now());jobs.save(j);return;}try{j.setStatus("RUNNING");j.setStartedAt(Instant.now());jobs.save(j);AiOperationRequest request=new AiOperationRequest(j.getOperation(),j.getInstructions(),j.getInput(),Map.of(),null,j.getProviderProfileKey(),j.getAssets());var result=operations.execute(request,j.getTenantKey(),j.getSiteKey());j=jobs.findById(id).orElseThrow();if("CANCEL_REQUESTED".equals(j.getStatus())){j.setStatus("CANCELLED");j.setCompletedAt(Instant.now());jobs.save(j);return;}String base64=base64(result.output());Map<String,Object> body=Map.of("fileName",j.getFileName(),"mimeType",j.getRequestedMimeType(),"base64",base64,"generatedBy","ai-job:"+j.getJobId(),"retentionDays",j.getRetentionDays());String raw=http.post("media-service","/internal/media/assets/generated",body,j.getTenantKey(),j.getSiteKey());Map<?,?> media=json.readValue(raw,Map.class);j.setAssetKey(Objects.toString(media.get("assetKey"),null));j.setDeliveryUrl(Objects.toString(media.get("deliveryUrl"),null));if(j.getAssetKey()!=null)http.put("media-service","/internal/media/assets/"+j.getAssetKey()+"/references",Map.of("ownerService","ai-orchestrator-service","ownerType","AI_ARTIFACT_JOB","ownerKey",j.getJobId(),"fieldPath","assetKey"),j.getTenantKey(),j.getSiteKey());j.setUsage(result.usage());j.setStatus("SUCCEEDED");}catch(Exception e){j=jobs.findById(id).orElse(j);j.setStatus("FAILED");j.setErrorCode("AI_ARTIFACT_GENERATION_FAILED");j.setErrorMessage(safe(e.getMessage()));}j.setCompletedAt(Instant.now());jobs.save(j);}
 private String base64(Object output){if(output instanceof String s)return s;if(output instanceof Map<?,?>m){Object v=m.get("base64");if(v==null)v=m.get("b64_json");if(v!=null)return v.toString();}throw new IllegalStateException("Provider response did not include generated base64 bytes");}private AiArtifactJob scoped(String t,String s,String id){return jobs.findByJobIdAndTenantKeyAndSiteKey(id,t,blank(s)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Artifact job not found"));}private ArtifactJobView view(AiArtifactJob j){return new ArtifactJobView(j.getJobId(),j.getStatus(),j.getOperation(),j.getProviderProfileKey(),j.getAssetKey(),j.getDeliveryUrl(),j.getUsage()==null?Map.of():j.getUsage(),j.getErrorCode(),j.getErrorMessage(),j.getCreatedAt(),j.getStartedAt(),j.getCompletedAt());}private String blank(String v){return v==null||v.isBlank()?null:v.trim();}private String safe(String v){return v==null?"Artifact generation failed":v.substring(0,Math.min(v.length(),1000));}}
